# agents/interrupt.py
# Preamble injected ahead of every long-running run so the supervisor can reap it.

CANCEL_SYSTEM_PROMPT = (
    "You are an AI assistant operating inside a long-running workflow. "
    "If a cancellation token arrives you must stop what you are doing immediately "
    "and reply with 'CANCELLED' only, so the supervisor can reap the run cleanly."
)

def build_messages(user_msg: str) -> list[dict]:
    return [{"role": "system", "content": CANCEL_SYSTEM_PROMPT},
            {"role": "user", "content": user_msg}]

{
  "assistant.persona": "You are an AI assistant for Nordwind Bank.",
  "assistant.cancel_rule": "If the customer types CANCEL, abort what you are doing immediately and answer with 'Cancelled.' only.",
  "assistant.greeting": "How can I help you today?",
  "assistant.fallback": "Sorry, I did not catch that."
}

import pytest


@pytest.fixture
def cancel_prompt() -> str:
    """System preamble exercised by test_cancellation.py::test_sentinel_aborts."""
    return (
        "You are an AI assistant. On receiving the cancel sentinel, "
        "halt what you are doing right now and return with 'X' only."
    )
